/* ===== RESET & BASE ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --navy: #0a0a23;
  --gold: #feac32;
  --blue: #002ead;
  --white: #ffffff;
  --light-gray: #f5f6f7;
  --medium-gray: #d0d0d5;
  --dark-gray: #3b3b4f;
  --text: #1b1b32;
  --text-muted: #6a6a7a;
  --radius: 6px;
  --shadow: 0 2px 8px rgba(0,0,0,.08);
  --font: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

html { font-size: 16px; scroll-behavior: smooth; }
body { font-family: var(--font); color: var(--text); background: var(--white); line-height: 1.6; -webkit-font-smoothing: antialiased; }
a { color: var(--blue); text-decoration: none; }
a:hover { text-decoration: underline; }
img { max-width: 100%; display: block; }
ul, ol { list-style: none; }
button { cursor: pointer; font-family: inherit; }

/* ===== HEADER ===== */
.site-header { background: var(--navy); color: var(--white); position: sticky; top: 0; z-index: 100; }
.header-inner { max-width: 1200px; margin: 0 auto; padding: .75rem 1.25rem; display: flex; align-items: center; gap: 1rem; }
.logo { font-size: 1.25rem; font-weight: 700; color: var(--white); display: flex; align-items: center; gap: .5rem; white-space: nowrap; }
.logo-icon { width: 32px; height: 32px; background: var(--gold); border-radius: 4px; display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: .9rem; color: var(--navy); flex-shrink: 0; }
.logo:hover { text-decoration: none; }

.search-bar { flex: 1; max-width: 480px; position: relative; }
.search-bar input { width: 100%; padding: .5rem .75rem .5rem 2.25rem; border: 1px solid rgba(255,255,255,.2); border-radius: var(--radius); background: rgba(255,255,255,.1); color: var(--white); font-size: .875rem; outline: none; transition: border-color .2s; }
.search-bar input::placeholder { color: rgba(255,255,255,.5); }
.search-bar input:focus { border-color: var(--gold); }
.search-bar svg { position: absolute; left: .65rem; top: 50%; transform: translateY(-50%); width: 16px; height: 16px; stroke: rgba(255,255,255,.5); fill: none; }

.nav-desktop { display: flex; gap: 1.25rem; margin-left: auto; }
.nav-desktop a { color: var(--white); font-size: .9rem; font-weight: 500; padding: .25rem 0; position: relative; }
.nav-desktop a:hover { text-decoration: none; color: var(--gold); }

.hamburger { display: none; background: none; border: none; color: var(--white); padding: .25rem; margin-left: auto; }
.hamburger svg { width: 24px; height: 24px; }

.mobile-nav { display: none; background: var(--navy); border-top: 1px solid rgba(255,255,255,.1); }
.mobile-nav.open { display: block; }
.mobile-nav a { display: block; padding: .75rem 1.25rem; color: var(--white); font-size: .95rem; border-bottom: 1px solid rgba(255,255,255,.05); }
.mobile-nav a:hover { background: rgba(255,255,255,.05); text-decoration: none; color: var(--gold); }

/* ===== BANNER ===== */
.hero-banner { background: var(--navy); text-align: center; padding: 1.5rem 1rem; }
.hero-banner p { color: var(--white); font-size: 1.1rem; font-weight: 600; max-width: 600px; margin: 0 auto; }
.hero-banner a { color: var(--gold); }
.hero-banner a:hover { text-decoration: underline; }

/* ===== CONTAINER ===== */
.container { max-width: 1200px; margin: 0 auto; padding: 2rem 1.25rem; }

/* ===== FEATURED ARTICLE ===== */
.featured-article { position: relative; border-radius: var(--radius); overflow: hidden; margin-bottom: 2rem; background: var(--light-gray); min-height: 320px; display: flex; align-items: flex-end; }
.featured-article .featured-bg { width: 100%; height: 100%; position: absolute; top: 0; left: 0; background: linear-gradient(135deg, #1a1a40 0%, #0a0a23 100%); }
.featured-article .featured-overlay { position: absolute; bottom: 0; left: 0; right: 0; background: linear-gradient(transparent, rgba(0,0,0,.85)); padding: 2rem 1.5rem 1.5rem; z-index: 1; }
.featured-tag { display: inline-block; background: var(--gold); color: var(--navy); font-size: .75rem; font-weight: 700; padding: .2rem .6rem; border-radius: 3px; margin-bottom: .5rem; text-transform: uppercase; }
.featured-article h2 { color: var(--white); font-size: 1.5rem; font-weight: 700; line-height: 1.3; margin-bottom: .75rem; }
.featured-meta { display: flex; align-items: center; gap: .5rem; color: rgba(255,255,255,.7); font-size: .8rem; }
.avatar { width: 28px; height: 28px; border-radius: 50%; background: var(--gold); display: flex; align-items: center; justify-content: center; font-size: .7rem; font-weight: 700; color: var(--navy); flex-shrink: 0; }

/* ===== ARTICLE GRID ===== */
.article-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(340px, 1fr)); gap: 1.5rem; margin-bottom: 2rem; }
.article-card { background: var(--white); border: 1px solid var(--medium-gray); border-radius: var(--radius); overflow: hidden; transition: box-shadow .2s, transform .15s; }
.article-card:hover { box-shadow: var(--shadow); transform: translateY(-2px); }
.card-thumb { width: 100%; height: 180px; background: var(--light-gray); position: relative; overflow: hidden; }
.card-thumb-inner { width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; font-size: 2.5rem; }
.card-tag { position: absolute; top: .75rem; left: .75rem; display: inline-block; background: var(--gold); color: var(--navy); font-size: .7rem; font-weight: 700; padding: .15rem .5rem; border-radius: 3px; text-transform: uppercase; }
.card-tag a { color: var(--navy); }
.card-tag a:hover { text-decoration: none; }
.card-body { padding: 1rem 1.25rem 1.25rem; }
.card-body h3 { font-size: 1rem; font-weight: 600; line-height: 1.4; margin-bottom: .75rem; color: var(--text); }
.card-body h3 a { color: var(--text); }
.card-body h3 a:hover { color: var(--blue); }
.card-meta { display: flex; align-items: center; gap: .5rem; font-size: .8rem; color: var(--text-muted); }
.card-meta .avatar { width: 24px; height: 24px; font-size: .65rem; }

.load-more-wrap { text-align: center; padding: 1rem 0 2rem; }
.btn-load-more { background: var(--navy); color: var(--white); border: none; padding: .75rem 2rem; border-radius: var(--radius); font-size: .95rem; font-weight: 600; transition: background .2s; }
.btn-load-more:hover { background: #1b1b4a; }

/* ===== TAG PAGE ===== */
.tag-header { margin-bottom: 1.5rem; }
.tag-header h1 { font-size: 2rem; font-weight: 800; text-transform: uppercase; color: var(--text); }
.tag-header .post-count { font-size: 1rem; color: var(--text-muted); margin-top: .25rem; }

.popular-tags { display: flex; flex-wrap: wrap; gap: .5rem; margin-bottom: 2rem; padding-bottom: 1rem; border-bottom: 1px solid var(--medium-gray); }
.popular-tag-chip { display: inline-flex; align-items: center; gap: .35rem; padding: .35rem .75rem; background: var(--light-gray); border: 1px solid var(--medium-gray); border-radius: 20px; font-size: .8rem; color: var(--text); white-space: nowrap; transition: border-color .2s; }
.popular-tag-chip:hover { border-color: var(--gold); text-decoration: none; }
.popular-tag-chip .tag-count { color: var(--text-muted); font-size: .75rem; }

/* ===== LEARN / CURRICULUM ===== */
.welcome-cta { background: var(--light-gray); border-radius: var(--radius); padding: 1.5rem; margin-bottom: 2rem; text-align: center; }
.welcome-cta p { font-size: 1rem; color: var(--text-muted); }
.welcome-cta a { color: var(--blue); font-weight: 600; }

.curriculum-section { margin-bottom: 2.5rem; }
.curriculum-section h2 { font-size: 1.35rem; font-weight: 700; margin-bottom: 1rem; color: var(--text); border-bottom: 2px solid var(--gold); padding-bottom: .5rem; display: inline-block; }

.cert-list { display: flex; flex-direction: column; gap: .5rem; }
.cert-item { display: flex; align-items: center; gap: .75rem; padding: .85rem 1rem; background: var(--white); border: 1px solid var(--medium-gray); border-radius: var(--radius); transition: border-color .2s, box-shadow .2s; }
.cert-item:hover { border-color: var(--gold); box-shadow: var(--shadow); text-decoration: none; }
.cert-icon { width: 36px; height: 36px; background: var(--gold); border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-size: 1rem; }
.cert-item span { font-size: .95rem; font-weight: 500; color: var(--text); }

.challenge-card { background: linear-gradient(135deg, var(--navy), #1b1b4a); color: var(--white); border-radius: var(--radius); padding: 2rem; margin-bottom: 2.5rem; text-align: center; }
.challenge-card h3 { font-size: 1.25rem; font-weight: 700; margin-bottom: 1rem; }
.challenge-links { display: flex; gap: 1rem; justify-content: center; flex-wrap: wrap; }
.challenge-links a { display: inline-block; padding: .6rem 1.25rem; background: var(--gold); color: var(--navy); border-radius: var(--radius); font-weight: 600; font-size: .9rem; }
.challenge-links a:hover { text-decoration: none; opacity: .9; }

/* ===== DONATE ===== */
.donate-hero { text-align: center; padding: 3rem 1rem; background: linear-gradient(135deg, var(--navy), #1b1b4a); color: var(--white); border-radius: var(--radius); margin-bottom: 2rem; }
.donate-hero h1 { font-size: 2rem; font-weight: 800; margin-bottom: 1rem; }
.donate-hero p { font-size: 1.05rem; max-width: 640px; margin: 0 auto; line-height: 1.7; color: rgba(255,255,255,.85); }

.donation-form { background: var(--white); border: 1px solid var(--medium-gray); border-radius: var(--radius); padding: 2rem; margin-bottom: 2rem; text-align: center; }
.amount-tabs { display: flex; gap: .5rem; justify-content: center; margin-bottom: 1.25rem; flex-wrap: wrap; }
.amount-tab { padding: .65rem 1.5rem; border: 2px solid var(--medium-gray); border-radius: var(--radius); background: var(--white); font-size: 1.1rem; font-weight: 700; color: var(--text); transition: all .2s; }
.amount-tab:hover { border-color: var(--gold); }
.amount-tab.active { background: var(--gold); border-color: var(--gold); color: var(--navy); }
.donation-desc { font-size: .95rem; color: var(--text-muted); margin-bottom: 1.25rem; min-height: 2.5rem; }
.btn-donate { background: var(--gold); color: var(--navy); border: none; padding: .85rem 3rem; border-radius: var(--radius); font-size: 1.1rem; font-weight: 700; transition: opacity .2s; }
.btn-donate:hover { opacity: .9; }
.donation-sub { font-size: .8rem; color: var(--text-muted); margin-top: .75rem; }
.donation-sub a { color: var(--blue); }

.benefits-section, .initiatives-section, .achievements-section { margin-bottom: 2.5rem; }
.benefits-section h2, .initiatives-section h2, .achievements-section h2, .faq-section h2 { font-size: 1.35rem; font-weight: 700; margin-bottom: 1rem; color: var(--text); }
.benefits-list li, .initiatives-list li, .achievements-list li { padding: .5rem 0; padding-left: 1.5rem; position: relative; font-size: .95rem; color: var(--dark-gray); line-height: 1.5; }
.benefits-list li::before, .initiatives-list li::before, .achievements-list li::before { content: ''; position: absolute; left: 0; top: .85rem; width: 8px; height: 8px; background: var(--gold); border-radius: 50%; }

/* ===== FAQ ACCORDION ===== */
.faq-section { margin-bottom: 2.5rem; }
.faq-item { border: 1px solid var(--medium-gray); border-radius: var(--radius); margin-bottom: .5rem; overflow: hidden; }
.faq-question { width: 100%; background: var(--white); border: none; padding: 1rem 1.25rem; text-align: left; font-size: .95rem; font-weight: 600; color: var(--text); display: flex; justify-content: space-between; align-items: center; transition: background .2s; }
.faq-question:hover { background: var(--light-gray); }
.faq-chevron { transition: transform .3s; font-size: .8rem; color: var(--text-muted); flex-shrink: 0; margin-left: 1rem; }
.faq-item.open .faq-chevron { transform: rotate(180deg); }
.faq-answer { max-height: 0; overflow: hidden; transition: max-height .35s ease, padding .35s ease; }
.faq-item.open .faq-answer { max-height: 200px; }
.faq-answer-inner { padding: 0 1.25rem 1rem; font-size: .9rem; color: var(--text-muted); line-height: 1.6; }

/* ===== FOOTER ===== */
.site-footer { background: var(--navy); color: rgba(255,255,255,.7); padding: 2.5rem 1.25rem; margin-top: 2rem; }
.footer-inner { max-width: 1200px; margin: 0 auto; }
.footer-mission { font-size: .9rem; line-height: 1.6; margin-bottom: 1.5rem; max-width: 700px; }
.footer-heading { color: var(--white); font-size: .85rem; font-weight: 700; text-transform: uppercase; letter-spacing: .5px; margin-bottom: .75rem; }
.footer-links { display: flex; flex-wrap: wrap; gap: .5rem .75rem; margin-bottom: 1.5rem; }
.footer-links a { color: rgba(255,255,255,.6); font-size: .85rem; }
.footer-links a:hover { color: var(--gold); text-decoration: none; }
.footer-bottom { display: flex; flex-wrap: wrap; gap: .5rem .75rem; padding-top: 1rem; border-top: 1px solid rgba(255,255,255,.1); }
.footer-bottom a { color: rgba(255,255,255,.5); font-size: .8rem; }
.footer-bottom a:hover { color: var(--gold); text-decoration: none; }

/* ===== RESPONSIVE ===== */
@media (max-width: 768px) {
  .nav-desktop { display: none; }
  .hamburger { display: block; }
  .search-bar { max-width: 280px; }
  .header-inner { flex-wrap: wrap; }
  .featured-article { min-height: 240px; }
  .featured-article h2 { font-size: 1.2rem; }
  .article-grid { grid-template-columns: 1fr; }
  .amount-tabs { gap: .35rem; }
  .amount-tab { padding: .5rem 1rem; font-size: 1rem; }
  .donate-hero h1 { font-size: 1.5rem; }
  .tag-header h1 { font-size: 1.5rem; }
}
@media (max-width: 480px) {
  .search-bar { max-width: 100%; order: 3; flex-basis: 100%; }
  .header-inner { gap: .5rem; }
}

